import random
import itertools

def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS to find cycles
    for start in range(n):
        # BFS with path tracking
        queue = [(start, [start])]
        visited_paths = {start: [[start]]}

        while queue:
            node, path = queue.pop(0)
            if len(path) == length:
                if start in adj[node]:
                    return True
                continue
            for neighbor in adj[node]:
                if neighbor == start and len(path) >= 3:
                    if len(path) == length - 1:
                        return True
                elif neighbor not in path:
                    new_path = path + [neighbor]
                    queue.append((neighbor, new_path))
    return False

def has_short_cycle(edges, n, max_girth=6):
    """Check if graph has any cycle of length < max_girth"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for cycles of length 3, 4, 5, 6
    for cycle_len in range(3, max_girth + 1):
        # Use BFS from each vertex
        for start in range(n):
            # BFS with depth limit
            queue = [(start, [start])]
            while queue:
                node, path = queue.pop(0)
                if len(path) == cycle_len:
                    if start in adj[node]:
                        return True
                    continue
                for neighbor in adj[node]:
                    if neighbor == start:
                        if len(path) == cycle_len - 1:
                            return True
                    elif neighbor not in path:
                        new_path = path + [neighbor]
                        if len(new_path) < cycle_len:
                            queue.append((neighbor, new_path))
    return False

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using backtracking"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

