# Let's try different bipartition sizes and more trials
import random
import itertools

def can_add_edge(edges, u, v, A, B, n):
    """Check if adding edge (u,v) creates a 4-cycle or 6-cycle"""
    adj = {i: set() for i in range(n)}
    for eu, ev in edges:
        adj[eu].add(ev)
        adj[ev].add(eu)
    adj[u].add(v)
    adj[v].add(u)

    # Check for 4-cycles
    for x in A:
        if x == u: continue
        if v not in adj[x]: continue
        for y in B:
            if y == v: continue
            if u in adj[y] and x in adj[y]:
                return False

    # Check for 6-cycles
    for x in A:
        if x == u: continue
        if v not in adj[x]: continue
        for y in B:
            if y == v: continue
            if x not in adj[y]: continue
            for z in A:
                if z in (u, x): continue
                if y not in adj[z]: continue
                for w in B:
                    if w in (v, y): continue
                    if z in adj[w] and u in adj[w]:
                        return False

    return True

def greedy_bipartite(a_size, b_size, n_trials=2000):
    n = a_size + b_size
    A = list(range(a_size))
    B = list(range(a_size, n))

    best_edges = []
    for trial in range(n_trials):
        edges = []
        all_possible = [(u, v) for u in A for v in B]
        random.shuffle(all_possible)

        for u, v in all_possible:
            if can_add_edge(edges, u, v, A, B, n):
                edges.append((u, v))

        if len(edges) > len(best_edges):
            best_edges = edges[:]
            if len(edges) >= 26:
                return best_edges

    return best_edges

