# Let's try a 3-partite graph approach
# Partition into 3 sets, edges only between different sets
# This guarantees 3-colorability
# We need to avoid cycles of length 3, 4, 5, 6

import random
import itertools

def can_add_edge_3partite(edges, u, v, parts, n):
    """Check if adding edge (u,v) creates a cycle of length 3-6"""
    # u and v must be in different parts
    part_u = -1
    part_v = -1
    for i, p in enumerate(parts):
        if u in p: part_u = i
        if v in p: part_v = i
    if part_u == part_v:
        return False

    adj = {i: set() for i in range(n)}
    for eu, ev in edges:
        adj[eu].add(ev)
        adj[ev].add(eu)
    adj[u].add(v)
    adj[v].add(u)

    # Check for cycles of length 3, 4, 5, 6
    for cycle_len in range(3, 7):
        # BFS from u
        queue = [(u, [u])]
        while queue:
            node, path = queue.pop(0)
            if len(path) == cycle_len:
                if v in adj[node]:
                    return False
                continue
            for neighbor in adj[node]:
                if neighbor == v and len(path) == cycle_len - 1:
                    return False
                elif neighbor not in path:
                    new_path = path + [neighbor]
                    if len(new_path) < cycle_len:
                        queue.append((neighbor, new_path))

    return True

def greedy_3partite(part_sizes, n_trials=5000):
    n = sum(part_sizes)
    parts = []
    start = 0
    for s in part_sizes:
        parts.append(list(range(start, start + s)))
        start += s

    best_edges = []
    for trial in range(n_trials):
        edges = []
        all_possible = []
        for i in range(len(parts)):
            for j in range(i+1, len(parts)):
                for u in parts[i]:
                    for v in parts[j]:
                        all_possible.append((u, v))
        random.shuffle(all_possible)

        for u, v in all_possible:
            if can_add_edge_3partite(edges, u, v, parts, n):
                edges.append((u, v))

        if len(edges) > len(best_edges):
            best_edges = edges[:]
            if len(edges) >= 26:
                return best_edges

    return best_edges

