import random
import itertools

def check_girth(edges, n, min_girth=7):
    """Check if graph has girth >= min_girth"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS
        dist = {start: 0}
        parent = {start: None}
        queue = [start]
        qi = 0
        while qi < len(queue):
            node = queue[qi]
            qi += 1
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def is_bipartite_3colorable(edges, n):
    """Bipartite graphs are 2-colorable, hence 3-colorable"""
    # Just check it's bipartite
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    color = {}
    for start in range(n):
        if start in color:
            continue
        color[start] = 0
        queue = [start]
        qi = 0
        while qi < len(queue):
            node = queue[qi]
            qi += 1
            for neighbor in adj[node]:
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
    return True

